BEGIN;
SET LOCAL search_path TO erp_auth;
CREATE TABLE IF NOT EXISTS members (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, permission TEXT NOT NULL CHECK(permission IN ('admin','manager','member')), status TEXT NOT NULL CHECK(status IN ('active','invited','disabled')), role TEXT NOT NULL, metadata_json TEXT NOT NULL, joined_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS invitations (hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires BIGINT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS api_keys (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,hash TEXT UNIQUE NOT NULL,name TEXT NOT NULL,scope TEXT NOT NULL CHECK(scope IN ('read','write')),prefix TEXT NOT NULL,last4 TEXT NOT NULL,created BIGINT NOT NULL,last_used BIGINT);
CREATE TABLE IF NOT EXISTS profile_photos (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,content BYTEA NOT NULL,mime_type TEXT NOT NULL,updated BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS app_webhooks (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,url TEXT NOT NULL,events_json TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN (0,1)),secret_encrypted TEXT NOT NULL,created BIGINT NOT NULL,updated BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_deliveries (id TEXT PRIMARY KEY,webhook_id TEXT NOT NULL REFERENCES app_webhooks(id) ON DELETE CASCADE,event TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL,created BIGINT NOT NULL,updated BIGINT NOT NULL,response_status INTEGER);
CREATE TABLE IF NOT EXISTS notification_states (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,notification_id TEXT NOT NULL,is_read INTEGER NOT NULL CHECK(is_read IN(0,1)),archived INTEGER NOT NULL CHECK(archived IN(0,1)),updated BIGINT NOT NULL,PRIMARY KEY(user_id,notification_id));
CREATE TABLE IF NOT EXISTS access_audit (id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,created BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS webhook_deliveries_created ON webhook_deliveries(created DESC);
ALTER TABLE members ENABLE ROW LEVEL SECURITY;
ALTER TABLE invitations ENABLE ROW LEVEL SECURITY;
ALTER TABLE api_keys ENABLE ROW LEVEL SECURITY;
ALTER TABLE profile_photos ENABLE ROW LEVEL SECURITY;
ALTER TABLE app_webhooks ENABLE ROW LEVEL SECURITY;
ALTER TABLE webhook_deliveries ENABLE ROW LEVEL SECURITY;
ALTER TABLE notification_states ENABLE ROW LEVEL SECURITY;
ALTER TABLE access_audit ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA erp_auth FROM PUBLIC, anon, authenticated;
COMMIT;
